    cases = sa.table('scrutiny_cases', sa.column('id', sa.Uuid()), sa.column('application_id', sa.Uuid()), sa.column('rule_version_id', sa.Uuid()), sa.column('state', sa.String()),
                     sa.column('row_version', sa.Integer()), sa.column('exception_code', sa.String()), sa.column('exception_detail', sa.Text()), sa.column('created_at', sa.DateTime(timezone=True)),
                     sa.column('updated_at', sa.DateTime(timezone=True)), sa.column('state_changed_at', sa.DateTime(timezone=True)))
    rounds = sa.table('scrutiny_rounds', sa.column('id', sa.Uuid()), sa.column('case_id', sa.Uuid()), sa.column('number', sa.Integer()), sa.column('kind', sa.String()),
                      sa.column('status', sa.String()), sa.column('opened_at', sa.DateTime(timezone=True)), sa.column('row_version', sa.Integer()))
    events = sa.table('scrutiny_events', sa.column('id', sa.Uuid()), sa.column('case_id', sa.Uuid()), sa.column('application_id', sa.Uuid()), sa.column('at', sa.DateTime(timezone=True)),
                      sa.column('actor_id', sa.Uuid()), sa.column('actor_label', sa.String()), sa.column('action', sa.String()), sa.column('object_type', sa.String()),
                      sa.column('object_id', sa.String()), sa.column('to_state', sa.String()), sa.column('detail', sa.JSON()), sa.column('institution_visible', sa.Boolean()))
    now = datetime.now(UTC)
    for row in bind.execute(sa.select(apps.c.id, apps.c.rule_version_id, apps.c.submitted_by_id, apps.c.submitted_at, apps.c.submission_snapshot).where(apps.c.status == 'SUBMITTED')):
        route = ((row.submission_snapshot or {}).get('configuration') or {}).get('route') or []
        ok = sum(1 for s in route if s.get('stage_key') == 'scrutiny') == 1
        state = 'AWAITING_ASSIGNMENT' if ok else 'CONFIGURATION_EXCEPTION'
        case_id = uuid.uuid4()
        at = row.submitted_at or now
        bind.execute(cases.insert().values(id=case_id, application_id=row.id, rule_version_id=row.rule_version_id, state=state, row_version=1,
                                           exception_code=None if ok else 'no_scrutiny_stage', exception_detail=None if ok else 'The approved route has no scrutiny stage.',
                                           created_at=now, updated_at=now, state_changed_at=now))
        if ok:
            bind.execute(rounds.insert().values(id=uuid.uuid4(), case_id=case_id, number=1, kind='INITIAL', status='OPEN', opened_at=now, row_version=1))
        name = bind.execute(sa.select(users.c.full_name).where(users.c.id == row.submitted_by_id)).scalar() if row.submitted_by_id else None
        bind.execute(events.insert().values(id=uuid.uuid4(), case_id=case_id, application_id=row.id, at=at, actor_id=row.submitted_by_id, actor_label=name or 'System', action='case_opened',
                                            object_type='scrutiny_case', object_id=str(case_id), to_state=state, detail={'backfilled': True}, institution_visible=True))


